/* banrProcDao1020 : 배너 저장 (수정) 처리 */
UPDATE BANR
	SET BANR_NM = #{banrNm, jdbcType=VARCHAR}
		,	BANR_SDT = TO_DATE(#{banrSdt, jdbcType=VARCHAR}, 'YYYY-MM-DD')
		,	BANR_EDT = TO_DATE(#{banrEdt, jdbcType=VARCHAR}, 'YYYY-MM-DD')
		,	BANR_URL = #{banrUrl, jdbcType=VARCHAR}
		,	FILE_ID = #{fileId, jdbcType=VARCHAR}
		,	USE_YN = #{useYn, jdbcType=VARCHAR}
		,	MOD_IDX = #{modIdx, jdbcType=VARCHAR}
		,	MOD_DT = SYSDATE
WHERE BANR_ID = #{banrId, jdbcType=VARCHAR}

/* banrProcDao1030 : 배너 삭제 처리 (수정)  */
UPDATE BANR
	SET USE_YN = 'N'
		,	MOD_IDX = #{modIdx, jdbcType=VARCHAR}
		,	MOD_DT = SYSDATE
WHERE BANR_ID = #{banrId, jdbcType=VARCHAR}
